#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "2mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Reordered and fused loops to work a row at a time (over i),
     improving cache locality for tmp and D.
   - Changed the k/j loop ordering so that the innermost loop walks
     contiguous memory in both operands (rows of B and C, rows of tmp
     and D), which is much more cache- and SIMD-friendly.
   - Added an OpenMP parallel-for over i (safe because iterations in i
     are independent). If compiled without -fopenmp, the pragmas are
     ignored and the code remains correct.
   - Preserved the per-element operation order: for each (i,j),
     tmp[i][j] and D[i][j] see exactly the same sequence of operations
     (initialization, scaling by beta, accumulation over k in
     increasing order) as in the original code.
*/
static
void kernel_2mm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
  /* D := alpha*A*B*C + beta*D
     The computation is reorganized, but for each element tmp[i][j] and
     D[i][j] the sequence of arithmetic operations is the same as in
     the original kernel (only interleaved differently across j). */

  /* Parallelize over rows. Each iteration in i works on one row of
     tmp and D and has no dependencies with other i's. */
#pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < _PB_NI; i++)
  {
    /* Row pointers for faster indexed access and to help the compiler
       with aliasing and vectorization. */
    DATA_TYPE *restrict tmp_i = tmp[i];
    DATA_TYPE *restrict D_i   = D[i];
    const DATA_TYPE *restrict A_i = A[i];

    /* ----------------------------------------------------------------
       1) tmp_i = alpha * A_i * B
          Original code:
            tmp[i][j] = 0;
            for k: tmp[i][j] += alpha * A[i][k] * B[k][j];
          Here we:
          - Initialize the entire row tmp_i to zero.
          - Loop over k outside j so B[k][j] is accessed row-wise.
          For any fixed (i,j), the operations on tmp[i][j] are:
             set to 0, then += term_k in increasing k,
          exactly as in the original.
       ---------------------------------------------------------------- */
    for (j = 0; j < _PB_NJ; j++)
      tmp_i[j] = SCALAR_VAL(0.0);

    for (k = 0; k < _PB_NK; ++k)
    {
      const DATA_TYPE a_ik = alpha * A_i[k];
      const DATA_TYPE *restrict B_k = B[k];

      /* Innermost j-loop: contiguous accesses to tmp_i[j] and B_k[j].
         #pragma GCC ivdep hints that there are no loop-carried
         dependencies preventing vectorization. */
#pragma GCC ivdep
      for (j = 0; j < _PB_NJ; ++j)
        tmp_i[j] += a_ik * B_k[j];
    }

    /* ----------------------------------------------------------------
       2) D_i *= beta
          Original code multiplies each D[i][j] by beta before adding
          the tmp*C contribution. We do the same here, per row.
       ---------------------------------------------------------------- */
    for (j = 0; j < _PB_NL; ++j)
      D_i[j] *= beta;

    /* ----------------------------------------------------------------
       3) D_i += tmp_i * C
          Original code:
            D[i][j] += sum_k tmp[i][k] * C[k][j];
          We compute it as:
            for k: for j: D[i][j] += tmp[i][k] * C[k][j];
          For any fixed (i,j), D[i][j] is still first multiplied by
          beta and then has contributions added for k in increasing
          order, exactly as before. C[k][j] is now accessed row-wise,
          improving locality and vectorization.
       ---------------------------------------------------------------- */
    for (k = 0; k < _PB_NJ; ++k)
    {
      const DATA_TYPE tmp_ik = tmp_i[k];
      const DATA_TYPE *restrict C_k = C[k];

#pragma GCC ivdep
      for (j = 0; j < _PB_NL; ++j)
        D_i[j] += tmp_ik * C_k[j];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}
