  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void __attribute__((noinline))
kernel_2mm(int ni, int nj, int nk, int nl,
	   DATA_TYPE alpha,
	   DATA_TYPE beta,
	   DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
	   DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
	   DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
	   DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
	   DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  /* Create local restrict-qualified aliases.  The POLYBENCH_2D macro
     expands to VLA function parameters; these pointer aliases make it
     easier for the compiler to optimize while still preserving all
     semantics of the original code. */
  DATA_TYPE (* __restrict tmp_)[nj] = tmp;
  DATA_TYPE (* __restrict A_)[nk]   = A;
  DATA_TYPE (* __restrict B_)[nj]   = B;
  DATA_TYPE (* __restrict C_)[nl]   = C;
  DATA_TYPE (* __restrict D_)[nl]   = D;

  /* Use PolyBench loop bounds, which may differ from the full array
     dimensions (ni, nj, nk, nl) when the harness requests smaller
     problem sizes. */
  const int ni_pb = _PB_NI;
  const int nj_pb = _PB_NJ;
  const int nk_pb = _PB_NK;
  const int nl_pb = _PB_NL;

  int i, j, k;

#pragma scop
  /* D := alpha*A*B*C + beta*D
   *
   * We apply the following optimizations while strictly preserving
   * the per-element floating-point evaluation order:
   *
   * 1. Reorder loops in the matrix multiplications to obtain
   *    unit-stride accesses to the innermost loop for better cache
   *    locality and vectorization (i,k,j instead of i,j,k).
   *    For each (i,j), the accumulation over k is still performed in
   *    increasing k order, so floating-point semantics are unchanged.
   *
   * 2. Introduce explicit OpenMP parallelization over the outer i loop
   *    (rows) where iterations are independent.  When compiled without
   *    OpenMP support, the pragmas are ignored and the code remains
   *    sequential.
   *
   * 3. Use local pointers with restrict and add vectorization hints
   *    to help the compiler generate efficient SIMD code.
   */

  /* -------- First phase: tmp = alpha * A * B -------- */

  /* Initialize tmp to zero (separate loop to mirror original behavior
     and keep the accumulation loops simpler and more vectorizable). */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j)
#endif
  for (i = 0; i < ni_pb; i++)
    for (j = 0; j < nj_pb; j++)
      tmp_[i][j] = SCALAR_VAL(0.0);

  /* Accumulate tmp += alpha * A * B
     Reordered loop nest: i, k, j.
     - For a fixed (i,j), the updates occur once per k from 0..nk_pb-1,
       exactly as in the original code, preserving summation order.
     - Innermost loop has unit-stride accesses to both tmp_[i][j] and
       B_[k][j], enhancing cache usage and SIMD efficiency. */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j,k)
#endif
  for (i = 0; i < ni_pb; i++)
  {
    for (k = 0; k < nk_pb; k++)
    {
      const DATA_TYPE a_ik_scaled = alpha * A_[i][k];
      const DATA_TYPE * __restrict Bk   = B_[k];
      DATA_TYPE       * __restrict tmpi = tmp_[i];

#pragma GCC ivdep
      for (j = 0; j < nj_pb; j++)
        tmpi[j] += a_ik_scaled * Bk[j];
    }
  }

  /* -------- Second phase: D = beta * D + tmp * C -------- */

  /* Step 1: scale D by beta.
     This is logically equivalent to the original "D[i][j] *= beta"
     inside the (i,j) loop, just performed as a separate pass. */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j)
#endif
  for (i = 0; i < ni_pb; i++)
  {
    DATA_TYPE * __restrict Di = D_[i];

#pragma GCC ivdep
    for (j = 0; j < nl_pb; j++)
      Di[j] *= beta;
  }

  /* Step 2: accumulate tmp * C into D.
     Reordered nest: i, k, j.  For a fixed (i,j), we:
